#!/bin/bash
# T1 setup: PG18 config + source database with the 20M-row table
set -euo pipefail
F=/var/lib/postgresql/18/main/postgresql.auto.conf
cat > $F <<'CONF'
# Do not edit this file manually!
# It will be overwritten by the ALTER SYSTEM command.
shared_preload_libraries = 'pg_stat_statements,pg_wait_sampling'
shared_buffers = '2GB'
log_lock_waits = 'on'
log_autovacuum_min_duration = '0'
autovacuum_naptime = '10s'
track_io_timing = 'on'
log_line_prefix = '%m [%p] %a '
CONF
chown postgres:postgres $F
systemctl restart postgresql@18-main
P="psql -X -q -h /var/run/postgresql -p 5418 -U postgres"
$P -d postgres -c "create extension if not exists pg_stat_statements" -c "create extension if not exists pg_wait_sampling"
$P -d postgres -c "drop database if exists trsrc" -c "create database trsrc"
$P -d trsrc <<'SQL'
create extension pg_prewarm;
create table t (id bigint primary key, grp int, payload text) with (autovacuum_enabled = false);
insert into t select g, g % 1000, repeat(md5(g::text), 2) from generate_series(1, 20000000) g;
vacuum (analyze, freeze) t;
alter table t set (autovacuum_vacuum_scale_factor = 0.01, autovacuum_vacuum_cost_delay = 0);
select pg_size_pretty(pg_relation_size('t')) heap, pg_size_pretty(pg_relation_size('t_pkey')) idx;
SQL
$P -d postgres -tAc "show shared_buffers; show shared_preload_libraries"
